    4: [[50, 86], [16, 58], [50, 12], [84, 58]],
    5: [[50, 86], [15, 58], [26, 18], [74, 18], [85, 58]],
    6: [[50, 86], [16, 58], [16, 26], [50, 12], [84, 26], [84, 58]],
